"use client"

import { RadioGroup as RadioGroupPrimitive } from "@base-ui/react/radio-group"
import { Radio as RadioPrimitive } from "@base-ui/react/radio"

import { cn } from "@/lib/utils"

// Frosted Glass Radio — empty glass ring; checked lights up with the same glass
// material as the primary Button. The dot is a glossy specular orb.

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

function RadioGroup({
  className,
  ...props
}: WithClassName<RadioGroupPrimitive.Props>) {
  return (
    <RadioGroupPrimitive data-slot="radio-group" className={cn("grid gap-2", className)} {...props} />
  )
}
RadioGroup.displayName = "RadioGroup"

function RadioGroupItem({
  className,
  ...props
}: WithClassName<RadioPrimitive.Root.Props>) {
  return (
    <RadioPrimitive.Root
      data-slot="radio-group-item"
      className={cn(
        "inline-flex items-center justify-center aspect-square h-5 w-5 rounded-full",
        "backdrop-blur-[var(--fg-blur)] backdrop-saturate-150 bg-[var(--fg-fill)]",
        "border border-[color:var(--fg-border)]",
        "shadow-[inset_0_0.0625rem_0_-0.0313rem_oklch(1_0_0/0.35)]",
        "transition-all duration-base",
        "hover:bg-[var(--fg-fill-hover)]",
        "focus:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-0",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-checked:bg-[var(--fg-fill-hover)] data-checked:shadow-[var(--fg-shadow)]",
        className
      )}
      {...props}
    >
      <RadioPrimitive.Indicator data-slot="radio-group-indicator" className="size-full flex items-center justify-center">
        <div className="h-2.5 w-2.5 rounded-full bg-[radial-gradient(circle_at_35%_30%,oklch(1_0_0),oklch(1_0_0/0.85)_55%,oklch(0.9_0.02_285/0.7))] shadow-[inset_0_0.0625rem_0_oklch(1_0_0/0.5),0_0_0.375rem_oklch(1_0_0/0.4)]" />
      </RadioPrimitive.Indicator>
    </RadioPrimitive.Root>
  )
}
RadioGroupItem.displayName = "RadioGroupItem"

export { RadioGroup, RadioGroupItem }
